return granted;

KeycloakSession session;
RealmModel realm;
ClientModel removedClient = null;
java.util.function.Consumer<MgmtPermissions> cleanup;

if (event instanceof RoleContainerModel.RoleRemovedEvent) {
    RoleContainerModel.RoleRemovedEvent cast = (RoleContainerModel.RoleRemovedEvent) event;
    RoleModel role = cast.getRole();
    session = cast.getKeycloakSession();
    realm = role.getContainer() instanceof ClientModel
            ? ((ClientModel) role.getContainer()).getRealm()
            : (RealmModel) role.getContainer();
    cleanup = permissions -> permissions.roles().setPermissionsEnabled(role, false);
} else if (event instanceof ClientModel.ClientRemovedEvent) {
    ClientModel.ClientRemovedEvent cast = (ClientModel.ClientRemovedEvent) event;
    session = cast.getKeycloakSession();
    realm = cast.getClient().getRealm();
    removedClient = cast.getClient();
    cleanup = permissions -> permissions.clients().setPermissionsEnabled(cast.getClient(), false);
} else if (event instanceof GroupModel.GroupRemovedEvent) {
    GroupModel.GroupRemovedEvent cast = (GroupModel.GroupRemovedEvent) event;
    session = cast.getKeycloakSession();
    realm = cast.getRealm();
    cleanup = permissions -> permissions.groups().setPermissionsEnabled(cast.getGroup(), false);
} else {
    return;
}

cleanup.accept(new MgmtPermissions(session, realm));

if (Profile.isFeatureEnabled(Profile.Feature.ADMIN_FINE_GRAINED_AUTHZ_V2)) {
    MgmtPermissionsV2 permissions = new MgmtPermissionsV2(session, realm);
    if (removedClient == null) {
        cleanup.accept(permissions);
    } else {
        org.keycloak.authorization.model.ResourceServer server = permissions.realmResourceServer();
        if (server != null) {
            org.keycloak.authorization.store.ResourceStore resourceStore = session
                    .getProvider(org.keycloak.authorization.AuthorizationProvider.class)
                    .getStoreFactory().getResourceStore();
            org.keycloak.authorization.model.Resource resource = resourceStore.findByName(
                    server, removedClient.getId(), server.getId());
            if (resource != null) {
                resourceStore.delete(resource.getId());
            }
        }
    }
}

if (resource == null) {
    // check if there is permission for "all-clients". If so, load its resource and proceed with evaluation
    resource = AdminPermissionsSchema.SCHEMA.getResourceTypeResource(session, server, AdminPermissionsSchema.CLIENTS_RESOURCE_TYPE);

    if (resource == null || authz.getStoreFactory().getPolicyStore().findByResource(server, resource).isEmpty()) {
        return false;
    }
